<script setup>
/* eslint-disable vue/no-bare-strings-in-template */
import { computed,onMounted,reactive,ref } from 'vue';import { commissionsAPI,salesOrdersAPI } from 'dashboard/api/crm/commercialCycle';import { useAlert } from 'dashboard/composables';
const rows=ref([]);const orders=ref([]);const loading=ref(false);const showForm=ref(false);const saving=ref(false);const form=reactive({sales_order_id:'',user_id:'',base:'0',rate_percent:5,status:'forecast',notes:''});const cents=v=>Math.round((Number(String(v).replace(',','.'))||0)*100);const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(v)||0)/100);const totals=computed(()=>({forecast:rows.value.filter(r=>r.status==='forecast').reduce((s,r)=>s+(Number(r.commission_cents)||0),0),released:rows.value.filter(r=>r.status==='released').reduce((s,r)=>s+(Number(r.commission_cents)||0),0),paid:rows.value.filter(r=>r.status==='paid').reduce((s,r)=>s+(Number(r.commission_cents)||0),0)}));const load=async()=>{loading.value=true;try{const [c,o]=await Promise.all([commissionsAPI.list(),salesOrdersAPI.list()]);rows.value=c.data||[];orders.value=o.data||[];}finally{loading.value=false;}};const selectOrder=()=>{const o=orders.value.find(x=>String(x.id)===String(form.sales_order_id));if(!o)return;form.user_id=o.owner?.id||'';form.base=((Number(o.products_cents)||0)-(Number(o.discount_cents)||0))/100;};const save=async()=>{saving.value=true;try{await commissionsAPI.create({commission:{sales_order_id:form.sales_order_id,user_id:form.user_id,base_cents:cents(form.base),rate_percent:Number(form.rate_percent),status:form.status,notes:form.notes}});showForm.value=false;await load();useAlert('Comissão criada.');}catch(e){useAlert(e.response?.data?.errors?.join(', ')||'Não foi possível criar a comissão.');}finally{saving.value=false;}};onMounted(load);
</script>
<template><div class="h-full overflow-auto bg-n-surface-1 p-4 sm:p-6"><header class="mb-5 flex flex-wrap items-center justify-between gap-3"><div class="flex items-center gap-3"><span class="grid size-11 place-content-center rounded-2xl bg-orange-50 text-orange-700"><i class="i-lucide-badge-dollar-sign size-5" /></span><div><h2 class="text-2xl font-bold">Comissões</h2><p class="text-sm text-n-slate-9">Comissões calculadas a partir das vendas, com frete fora da base por padrão.</p></div></div><button class="rounded-xl bg-n-brand px-4 py-2.5 text-sm font-semibold text-white" @click="showForm=true">+ Nova comissão</button></header><section class="mb-4 grid gap-3 sm:grid-cols-3"><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Prevista</p><strong class="text-xl">{{ money(totals.forecast) }}</strong></article><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Liberada</p><strong class="text-xl text-amber-700">{{ money(totals.released) }}</strong></article><article class="rounded-2xl border border-n-weak bg-white p-4"><p class="text-xs text-n-slate-9">Paga</p><strong class="text-xl text-emerald-700">{{ money(totals.paid) }}</strong></article></section><div class="overflow-hidden rounded-2xl border border-n-weak bg-white"><table class="w-full text-sm"><thead class="bg-n-alpha-2 text-left text-xs uppercase text-n-slate-9"><tr><th class="p-3">Venda</th><th class="p-3">Vendedor</th><th class="p-3">Base</th><th class="p-3">%</th><th class="p-3">Comissão</th><th class="p-3">Status</th></tr></thead><tbody class="divide-y divide-n-weak"><tr v-if="loading"><td colspan="6" class="p-10 text-center">Carregando…</td></tr><tr v-for="row in rows" :key="row.id"><td class="p-3 font-semibold">{{ row.order?.order_number||`#${row.order?.id}` }}</td><td class="p-3">{{ row.user?.name||'—' }}</td><td class="p-3">{{ money(row.base_cents) }}</td><td class="p-3">{{ row.rate_percent }}%</td><td class="p-3 font-semibold">{{ money(row.commission_cents) }}</td><td class="p-3"><span class="rounded-full bg-orange-50 px-2 py-1 text-xs font-semibold text-orange-700">{{ row.status }}</span></td></tr><tr v-if="!loading&&!rows.length"><td colspan="6" class="p-10 text-center text-n-slate-9">Nenhuma comissão calculada.</td></tr></tbody></table></div><Teleport to="body"><div v-if="showForm" class="fixed inset-0 z-[90] grid place-content-center bg-black/45 p-4" @click.self="showForm=false"><form class="w-full max-w-lg rounded-2xl bg-white p-6" @submit.prevent="save"><h3 class="text-xl font-bold">Nova comissão</h3><p class="mt-1 text-sm text-n-slate-9">A base sugerida usa produtos menos descontos e não inclui frete.</p><div class="mt-5 grid gap-3"><label class="text-sm">Pedido/Venda<select v-model="form.sales_order_id" required class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" @change="selectOrder"><option value="">Selecione</option><option v-for="order in orders" :key="order.id" :value="order.id">{{ order.order_number }} — {{ order.contact?.name }} — {{ money(order.total_cents) }}</option></select></label><label class="text-sm">Base da comissão (R$)<input v-model="form.base" type="number" min="0" step="0.01" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Percentual (%)<input v-model.number="form.rate_percent" type="number" min="0" step="0.1" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label><label class="text-sm">Status<select v-model="form.status" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2"><option value="forecast">Prevista</option><option value="released">Liberada</option><option value="paid">Paga</option></select></label><label class="text-sm">Observações<textarea v-model="form.notes" rows="2" class="mt-1 w-full rounded-lg border border-n-weak px-3 py-2" /></label></div><div class="mt-5 flex justify-end gap-2"><button type="button" class="rounded-lg border border-n-weak px-4 py-2" @click="showForm=false">Cancelar</button><button :disabled="saving||!form.user_id" class="rounded-lg bg-n-brand px-4 py-2 font-semibold text-white disabled:opacity-50">Criar comissão</button></div></form></div></Teleport></div></template>
